import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { registerRootComponent } from "expo";

function App() {
  const [count, setCount] = useState(0);

  // энд бичнэ үү: эхэнд хадгалсан утгаа уншиж ачаал

  const add = () => {
    const next = count + 1;
    setCount(next);
    // энд бичнэ үү: шинэ утгаа хадгал
  };

  return (
    <View style={styles.screen}>
      <Text nativeID="count" style={styles.count}>Сагс: {count}</Text>
      <Pressable nativeID="add" style={styles.btn} onPress={add}>
        <Text style={styles.btnText}>Сагслах</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 16, justifyContent: "center", alignItems: "center" },
  count: { fontSize: 24, fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", paddingVertical: 14, paddingHorizontal: 28, borderRadius: 12 },
  btnText: { color: "#fff", fontSize: 16, fontWeight: "bold" },
});

registerRootComponent(App);

